-- ═══════════════════════════════════════════════════════════════════════
--  STACKCLASS — RompeCódigos: Partidas de Entrenamiento (20 Operaciones)
--  Ejecutar en: Supabase Dashboard → SQL Editor
-- ═══════════════════════════════════════════════════════════════════════

-- 1. CREACIÓN DE LA TABLA
CREATE TABLE IF NOT EXISTS rompecodigos_partidas (
  id SERIAL PRIMARY KEY,
  numero INTEGER NOT NULL UNIQUE,
  nombre TEXT NOT NULL,
  descripcion TEXT,
  clave_vigenere_1 TEXT NOT NULL,
  clave_vigenere_2 TEXT NOT NULL,
  misiones JSONB NOT NULL,
  active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. HABILITAR ROW LEVEL SECURITY (RLS)
ALTER TABLE rompecodigos_partidas ENABLE ROW LEVEL SECURITY;

-- 3. POLÍTICAS DE ACCESO
DROP POLICY IF EXISTS "rompe_partidas_read" ON rompecodigos_partidas;
CREATE POLICY "rompe_partidas_read" ON rompecodigos_partidas
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "rompe_partidas_write" ON rompecodigos_partidas;
CREATE POLICY "rompe_partidas_write" ON rompecodigos_partidas
  FOR ALL USING (is_teacher() OR is_admin());

-- 4. INSERTAR O ACTUALIZAR LAS 20 OPERACIONES COMPLETAS
